import { unstable_cache } from 'next/cache';
import { getPosts } from '@/lib/api';

// Define the shape of a post based on the API response
interface Post {
  id: number;
  title: string;
  author: string;
}

// Create a cached version of the data fetching function
const getCachedPosts = unstable_cache(
  async () => getPosts(),
  ['posts'], // Cache key parts
  {
    revalidate: 3600, // Revalidate every hour
    tags: ['posts'], // Tag for on-demand invalidation
  }
);

export default async function Home() {
  const posts = await getCachedPosts();

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post: Post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}

